select jsi.*, count(jsr.id) as sportCount from jw_schedule_item jsi
left join jw_sign_record jsr on jsr.schedule_item_id = jsi.id

     and jsi.match_id = #{matchId}
     and jsi.game_item_id = #{gameItemId}
     and jsi.schedule_info_id = #{scheduleInfoId}
     and jsi.schedule_place_id = #{schedulePlaceId}
     and jsi.item_name like concat('%', #{itemName}, '%')
     and jsi.shcedule_time = #{shceduleTime}
     and jsi.area = #{area}
     and jsi.item_process = #{itemProcess}
     and jsi.lock_score = #{lockScore}

group by jsi.id

