match_id = #{matchId}, game_item_id = #{gameItemId}, schedule_info_id = #{scheduleInfoId}, schedule_place_id = #{schedulePlaceId}, item_name = #{itemName}, shcedule_time = #{shceduleTime}, area = #{area}, item_process = #{itemProcess}, lock_score = #{lockScore},
where id = #{id}

